<style lang="scss" src="./select.scss"></style>

<script>
import get from "lodash/get";
import sortBy from "lodash/sortBy";
import { Component, Prop, Vue } from "vue-property-decorator";
import { IconShape } from "../icon/icon.constants";
import Icon from "../icon/icon.vue";
import Popover from "../popover/popover";
import Scroll from "../scroll/scroll";
import List from "./list/list.vue";

/**
 * This is an uncontrolled select menu.
 * This component requires the `value` prop to be supplied by the parent.
 * In addition, a handler is required for the `@select` event.
 * For single select, the handler should look something like this:
 *
 * ```
 * handleSelect: (newValue) => {
 *   this.value = newValue;
 * },
 * ```
 *
 * For multiselect, the handler should look something like this:
 *
 * ```
 * handleSelect: (newValue) => {
 *   this.value = typeof newValue === "string" ? newValue.split(",") : newValue,
 * },
 * ```
 *
 * The `typeof newValue === "string"` check is for when autofill may happen,
 * in which case, the value would populated as a string.
 */
@Component({
  components: {
    Icon,
    List,
    Popover,
    Scroll,
  },
})
export default class Select extends Vue {
  @Prop({
    type: String,
    required: true,
  })
  label;

  /**
   * The choices a user can choose from.
   * e.g.
   * [
   *  { label: "Choice 1", value: 1 },
   *  { label: "Choice 2", value: 2 },
   *  { label: "Choice 3", value: 3 },
   * ]
   */
  @Prop({
    type: Array,
    default: () => [],
    required: true,
  })
  items;

  /**
   * The currently selected value(s).
   *
   * If not in `multiselect` mode, `value` should be a string/number.
   * e.g. 1 (from the sample above)
   *
   * If in `multiselect` mode, `value` should be an array of values.
   * e.g. [1, 2, 3] (from the sample above)
   */
  @Prop({
    type: [Number, String, Array, Boolean],
    required: false,
  })
  value;

  /**
   * If true, allows users to select more than one value
   */
  @Prop({
    type: Boolean,
    default: false,
  })
  multiselect;

  /**
   * If true, enables users to search for a choice
   */
  @Prop({
    type: Boolean,
    default: false,
  })
  search;

  /**
   * If true, disables the select
   */
  @Prop({
    type: Boolean,
    default: false,
  })
  disabled;

  /**
   * If true, hides the arrow icon
   */
  @Prop({
    type: Boolean,
    default: false,
  })
  hideArrow;

  /**
   * Allows styling customization of each of the items
   * :itemStyle="
   *   (item) => ({
   *     background: {
   *       normal: 'rgba(2, 0, 38, 0.05)',
   *       hover: 'rgba(2, 0, 38, 0.15)',
   *       active: 'rgba(2, 0, 38, 0.25)',
   *       selected: {
   *         normal: 'rgba(2, 0, 38, 0.15)',
   *         hover: 'rgba(2, 0, 38, 0.25)',
   *         active: 'rgba(2, 0, 38, 0.35)',
   *       },
   *     },
   *     text: {
   *       normal: 'black',
   *     },
   *     iconStart: {
   *       show: item.icon != undefined && !Number.isNaN(item.icon),
   *       iconProps: {
   *         shape: item.icon,
   *         color: '#2356F6',
   *       },
   *     },
   *     iconEnd: {
   *       show: item.favourite != undefined,
   *       iconProps: {
   *         shape: item.favourite
   *           ? IconShape.STAR_FULL
   *           : IconShape.STAR_EMPTY,
   *         color: '#57BFA1',
   *       },
   *     },
   *     indicator:
   *       item.mode === 'primary'
   *         ? '#2356F6'
   *         : item.mode === 'secondary'
   *         ? '#656677'
   *         : undefined,
   *   })
   * "
   */
  @Prop({
    type: Function,
    default: () => () => {},
  })
  itemStyle;

  /**
   * Allows styling customization of the trigger.
   *
   * :triggerStyle="
   *   (item) => ({
   *     border: 'none',
   *     background: {
   *       normal: 'red',
   *       hover: 'green',
   *       active: 'pink,',
   *     },
   *     text: {
   *       normal: 'blue',
   *       hover: 'orange',
   *       active: 'yellow',
   *     },
   *     iconStart: {
   *       show: true,
   *       iconProps: {
   *         shape: item.icon,
   *         color: 'yellow',
   *       },
   *     },
   *     iconEnd: {
   *       show: true,
   *       iconProps: {
   *         shape: item.favourite
   *           ? IconShape.STAR_FULL
   *           : IconShape.STAR_EMPTY,
   *         color: '#57BFA1',
   *       },
   *     },
   *     arrowIcon: {
   *       show: false,
   *       color: {
   *         enabled: 'white',
   *         disabled: 'blue',
   *       },
   *     },
   *   })
   */
  @Prop({
    type: Function,
    default: () => () => {},
  })
  triggerStyle;

  /**
   * On mount, set the default value of the select.
   * If the value is provided, select the item within the items with the corresponding value.
   * Otherwise, select the first item in the list.
   */
  mounted() {
    const isNoInitialValue = this.value == undefined || this.value === "";
    const isMultiselect = this.multiselect;

    // calculate value argument
    const fallbackValue = this.items?.[0]?.value;
    const valueArg = isNoInitialValue ? fallbackValue : this.value;

    // calculate item argument
    const fallbackItem = this.items[0];
    const item = isMultiselect ? undefined : this.currentItem;
    const itemArg = isNoInitialValue ? fallbackItem : item;

    this.handleSelect(valueArg, itemArg);
  }

  get IconShape() {
    return IconShape;
  }

  getItemPropWithValue(prop) {
    return (value) => this.items.find((item) => item.value === value)?.[prop];
  }

  get currentItem() {
    if (this.multiselect) {
      return undefined;
    }

    const currentItem = this.items.find((item) => item.value === this.value);

    if (!currentItem) {
      return undefined;
    }

    return currentItem;
  }

  /**
   * A getter returning true if there is nothing selected
   */
  get ifNoValue() {
    return (
      (this.multiselect && !this.value?.length) ||
      (!this.multiselect && (this.value == undefined || this.value === ""))
    );
  }

  /**
   * A getter returning the label to show in the dropdown trigger button
   */
  get triggerText() {
    const getItemLabel = this.getItemPropWithValue("label");

    if (this.ifNoValue) {
      return this.label;
    }

    if (this.multiselect) {
      const originalOrderArray = sortBy(this.value, (val) =>
        this.items.findIndex((item) => item.value === val)
      );
      return originalOrderArray
        .map(getItemLabel)
        .filter(Boolean)
        .join(", ");
    } else {
      return getItemLabel(this.value);
    }
  }

  get triggerButtonStyling() {
    return {
      border: this.getTriggerStyle("border"),
      "--trigger-bg--normal": this.getTriggerStyle("background.normal"),
      "--trigger-bg--hover": this.getTriggerStyle("background.hover"),
      "--trigger-bg--active": this.getTriggerStyle("background.active"),
      "--trigger-text--normal": this.getTriggerStyle("text.normal"),
      "--trigger-text--hover": this.getTriggerStyle("text.hover"),
      "--trigger-text--active": this.getTriggerStyle("text.active"),
    };
  }

  getTriggerStyle(args) {
    return get(this.triggerStyle(this.currentItem || {}), args);
  }

  get iconStartProps() {
    const defaultIconProps = {
      color: "#2356F6",
      size: 20,
    };
    return {
      ...defaultIconProps,
      ...this.getTriggerStyle("iconStart.iconProps"),
    };
  }

  get iconEndProps() {
    const defaultIconProps = {
      color: "#2356F6",
      size: 20,
    };
    return {
      ...defaultIconProps,
      ...this.getTriggerStyle("iconEnd.iconProps"),
    };
  }

  get arrowIcon() {
    const defaultArrowIcon = {
      show: true,
      color: "black",
    };
    return { ...defaultArrowIcon, ...this.getTriggerStyle("arrowIcon") };
  }

  handleSelect(itemValue, item, close) {
    if (item) {
      if (this.multiselect) {
        const set = new Set(this.value);

        if (set.has(itemValue)) {
          set.delete(itemValue);
        } else {
          set.add(itemValue);
        }

        this.$emit("select", [...set], item);
      } else {
        this.$emit("select", itemValue, item);
        close?.();
      }
    }
  }
}
</script>

<template>
  <div class="Select">
    <Popover>
      <!-- the target element that opens the select -->
      <template #trigger="{ open, isOpen }">
        <div class="Select__TriggerContainer">
          <button
            :class="[
              'Select__Trigger',
              {
                'Select__Trigger--WithStartIcon': !!getTriggerStyle(
                  'iconStart.show'
                ),
                'Select__Trigger--WithOneEndIcon':
                  (arrowIcon.show && !getTriggerStyle('iconEnd.show')) ||
                  (!arrowIcon.show && getTriggerStyle('iconEnd.show')),
                'Select__Trigger--WithTwoEndIcons':
                  arrowIcon.show && getTriggerStyle('iconEnd.show'),
                'Select__Trigger--NoValue': ifNoValue,
                'Select__Trigger--Disabled': disabled,
              },
            ]"
            :style="triggerButtonStyling"
            @click="open"
            :disabled="disabled"
            :aria-label="label"
            :aria-expanded="isOpen.toString()"
          >
            <div
              v-if="getTriggerStyle('iconStart.show')"
              class="Select__TriggerIcon Select__TriggerIcon--Start"
            >
              <!-- used a 'key' prop here to make vue re-render when 
            a new selection is made -->
              <Icon v-bind="{ ...iconStartProps, key: currentItem.value }" />
            </div>
            <Scroll>
              <div
                :class="[
                  'Select__TriggerText',
                  {
                    'Select__TriggerText--WithLeftIcon': getTriggerStyle(
                      'iconStart.show'
                    ),
                  },
                ]"
              >
                {{ triggerText }}
              </div>
            </Scroll>

            <!-- END ICON -->
            <div
              v-if="getTriggerStyle('iconEnd.show')"
              :class="[
                'Select__TriggerIcon',
                'Select__TriggerIcon--EndIcon',
                {
                  'Select__TriggerIcon--EndIconWithArrow': arrowIcon.show,
                },
              ]"
            >
              <Icon v-bind="iconEndProps" />
            </div>

            <!-- ARROW ICON -->
            <div
              v-if="arrowIcon.show"
              :class="['Select__TriggerIcon', 'Select__TriggerIcon--Arrow']"
            >
              <Icon
                :shape="isOpen ? IconShape.CHEVRON_UP : IconShape.CHEVRON_DOWN"
                :size="20"
                :color="
                  disabled
                    ? arrowIcon.color.disabled || '#dadce8'
                    : arrowIcon.color.enabled || '#000'
                "
              />
            </div>
          </button>
        </div>
      </template>

      <!-- content to render in the popover -->
      <template #popover="{ close }">
        <List
          :multiselect="multiselect"
          :search="search"
          :value="value"
          :items="items"
          :itemStyle="itemStyle"
          @click="(value, item) => handleSelect(value, item, close)"
        />
      </template>
    </Popover>
  </div>
</template>
